259	     */
260	    private String generateCustomerCode(String lastName) {
261	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
262	        long sequence = ownerRepository.findAll().size() + 1L;
263	        return String.format("%s-%04d", prefix, sequence);
