279	     */
280	    private void assertTelephoneUnique(Owner owner, String normalized) {
281	        if (normalized == null || normalized.isEmpty()) {
282	            return;
283	        }
284	        for (Owner existing : ownerRepository.findAll()) {
285	            if (!existing.getId().equals(owner.getId())
286	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
287	                throw new DuplicateTelephoneException(normalized);
288	            }
289	        }
290	    }
