294	     * (compared case-insensitively with collapsed whitespace) with an existing owner, unless the
295	     * request explicitly acknowledges the shared household via {@link Owner#isSharesHousehold()}.
296	     * Only applies to new owners; updates to an existing owner are left untouched.
297	     *
298	     * @throws DuplicateHouseholdException if another owner already lives at the same household
299	     */
300	    private void assertHouseholdAllowed(Owner owner) {
301	        if (!owner.isNew() || owner.isSharesHousehold()) {
302	            return;
303	        }
304	        String lastName = normalizeHouseholdValue(owner.getLastName());
305	        String address = normalizeHouseholdValue(owner.getAddress());
306	        if (lastName.isEmpty() || address.isEmpty()) {
307	            return;
308	        }
309	        for (Owner existing : ownerRepository.findAll()) {
310	            if (!existing.getId().equals(owner.getId())
311	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
312	                    && address.equals(normalizeHouseholdValue(existing.getAddress()))) {
313	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
314	            }
315	        }
