18	/**
19	 * Normalizes telephone numbers into <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
20	 * form. Spaces, dashes and brackets are stripped. A number that already carries a leading
21	 * {@code '+'} keeps its explicit country code; otherwise the Australian country code
22	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
23	 * digits. The result must contain between 8 and 15 digits after the {@code '+'}, matching
24	 * the E.164 length rule.
25	 *
26	 * <p>The same logic backs both the request-time validator (so a number that cannot form
27	 * valid E.164 is rejected with HTTP 400) and the normalization applied before an
28	 * {@code Owner} is persisted, so the value a client is told about matches the value that
29	 * gets stored and compared for duplicates.
30	 */
31	public final class E164Telephone {
32	
33	    private E164Telephone() {
34	    }
35	
36	    /**
37	     * Convert a raw telephone number to E.164 form, or return {@code null} if it cannot
38	     * form a valid E.164 number.
39	     *
40	     * @param raw the raw telephone number as supplied by the client (may be {@code null})
41	     * @return the normalized {@code +<digits>} string, or {@code null} when invalid
42	     */
43	    public static String toE164(String raw) {
44	        if (raw == null) {
45	            return null;
46	        }
47	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
48	        String digits;
49	        if (cleaned.startsWith("+")) {
50	            String body = cleaned.substring(1);
51	            if (!body.matches("\\d+")) {
52	                return null;
53	            }
54	            digits = body;
55	        }
56	        else {
57	            if (!cleaned.matches("\\d+")) {
58	                return null;
59	            }
60	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
61	            digits = "61" + national;
62	        }
63	        if (digits.length() < 8 || digits.length() > 15) {
64	            return null;
65	        }
66	        return "+" + digits;
67	    }
68	}
