43	/**
44	 * Global Exception handler for REST controllers.
45	 * <p>
46	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
47	 *
48	 * @author Vitaliy Fedoriv
49	 * @author Alexander Dudkin
50	 */
51	@ControllerAdvice
52	public class ExceptionControllerAdvice {
53	
54	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
55	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
56	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
57	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
58	
59	    /**
60	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
61	     * class.
62	     *
63	     * @param e     Object referring to the thrown exception.
64	     * @param status HTTP response status.
65	     * @param url URL request.
66	     */
67	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
68	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
69	        problemDetail.setType(URI.create(url.toString()));
70	        problemDetail.setTitle(e.getClass().getSimpleName());
71	        problemDetail.setDetail(detail);
72	        problemDetail.setProperty("timestamp", Instant.now());
73	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
74	        return problemDetail;
75	    }
76	
77	    /**
78	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
79	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
80	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
81	     * would catch it and report an authorization failure as a 500.
82	     *
83	     * @param e The {@link AccessDeniedException} to propagate
84	     * @throws AccessDeniedException always
85	     */
86	    @ExceptionHandler(AccessDeniedException.class)
87	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
88	        throw e;
89	    }
90	
91	    /**
92	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
93	     *
94	     * @param e The {@link Exception} to be handled
95	     * @param request {@link HttpServletRequest} object referring to the current request.
96	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
97	     */
98	    @ExceptionHandler(Exception.class)
99	    @ResponseBody
100	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
101	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
102	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
103	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
109	     * method returns a 404 Not Found status if an entity does not exist.
110	     *
111	     * @param e The {@link DataIntegrityViolationException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
114	     */
115	    @ExceptionHandler(DataIntegrityViolationException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
118	        logger.warn("Data integrity violation at {} {}: {}",
119	            request.getMethod(),
120	            request.getRequestURI(),
121	            e.getMessage());
122	        logger.debug("Data integrity violation stacktrace", e);
123	        HttpStatus status = HttpStatus.NOT_FOUND;
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
125	        return ResponseEntity.status(status).body(detail);
126	    }
127	
128	    /**
129	     * Handles {@link DuplicateTelephoneException}, raised when an owner is created or updated with a
130	     * normalized telephone number already used by another owner. Returns a 409 Conflict status.
131	     *
132	     * @param e The {@link DuplicateTelephoneException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
135	     */
136	    @ExceptionHandler(DuplicateTelephoneException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
139	        logger.warn("Duplicate telephone at {} {}: {}",
140	            request.getMethod(),
141	            request.getRequestURI(),
142	            e.getMessage());
143	        HttpStatus status = HttpStatus.CONFLICT;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
145	        return ResponseEntity.status(status).body(detail);
146	    }
147	
148	    /**
149	     * Handles {@link DuplicateHouseholdException}, raised when an owner is created with the same
150	     * lastName and address (compared case-insensitively with collapsed whitespace) as an existing
151	     * owner without acknowledging the shared household. Returns a 409 Conflict status.
152	     *
153	     * @param e The {@link DuplicateHouseholdException} to be handled
154	     * @param request {@link HttpServletRequest} object referring to the current request.
155	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
156	     */
157	    @ExceptionHandler(DuplicateHouseholdException.class)
158	    @ResponseBody
159	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
160	        logger.warn("Duplicate household at {} {}: {}",
161	            request.getMethod(),
162	            request.getRequestURI(),
163	            e.getMessage());
164	        HttpStatus status = HttpStatus.CONFLICT;
165	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
166	        return ResponseEntity.status(status).body(detail);
167	    }
168	
169	    /**
170	     * Handles exception thrown by Bean Validation on controller methods parameters
171	     *
172	     * @param e The {@link MethodArgumentNotValidException} to be handled
173	     * @param request {@link HttpServletRequest} object referring to the current request.
174	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
175	     */
176	    @ExceptionHandler(MethodArgumentNotValidException.class)
177	    @ResponseBody
178	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
179	        HttpStatus status = HttpStatus.BAD_REQUEST;
180	        BindingErrorsResponse errors = new BindingErrorsResponse();
181	        BindingResult bindingResult = e.getBindingResult();
182	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
183	        if (bindingResult.hasErrors()) {
184	            errors.addAllErrors(bindingResult);
185	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
186	                .map(fieldError -> {
187	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
188	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
189	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
190	                        fieldError.getField(),
191	                        defaultMessage,
192	                        rejectedValue);
193	                    return new ValidationMessageDto(message)
194	                        .putAdditionalProperty("field", fieldError.getField())
195	                        .putAdditionalProperty("rejectedValue", rejectedValue)
196	                        .putAdditionalProperty("defaultMessage", defaultMessage);
197	                })
198	                .toList();
199	            logger.debug("Validation error at {} {}: {}",
200	                request.getMethod(),
201	                request.getRequestURI(),
202	                bindingResult.getFieldErrors());
203	            List<String> errorFields = bindingResult.getFieldErrors().stream()
204	                .map(FieldError::getField)
205	                .distinct()
206	                .toList();
207	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
208	            detail.setProperty("errors", errorFields);
209	            return ResponseEntity.status(status).body(detail);
210	        }
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	}
