```java
@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    if (owner.getTelephone() != null) {
        owner.setTelephone(normalizeTelephone(owner.getTelephone()));   // E.164 normalize
    }
    if (owner.getEmail() != null) {
        owner.setEmail(normalizeEmail(owner.getEmail()));               // lower-case
    }
    if (owner.getRegistrationDate() == null) {
        owner.setRegistrationDate(LocalDate.now());                     // default today
    }
    if (owner.getCustomerCode() == null) {
        owner.setCustomerCode(generateCustomerCode(owner.getLastName())); // <LAST3>-NNNN
    }
    assertTelephoneUnique(owner, owner.getTelephone());                 // may throw 409
    assertHouseholdAllowed(owner);                                      // may throw 409
    ownerRepository.save(owner);
}
```

